QARIS.forEach(q=>$('qari').append(node('option',{value:q.id,text:q.name})));$('qari').value=qari;$('qari').onchange=()=>{qari=$('qari').value;try{storage?.setItem('qwbw.qari',JSON.stringify(qari));}catch{}stopAudio();};
