 for(const b of document.querySelectorAll('[data-story-theme]'))b.onclick=()=>{shareTheme=b.dataset.storyTheme;for(const t of document.querySelectorAll('[data-story-theme]'))t.setAttribute('aria-pressed',String(t===b));refreshStoryPreview();};
 $('story-prev').onclick=()=>showStoryPage(sharePage-1);$('story-next').onclick=()=>showStoryPage(sharePage+1);$('share-story').onclick=shareStoryImage;$('download-story').onclick=downloadStoryImage;$('story-save-draft').onclick=saveStoryDraft;$('share-text').onclick=shareAyahText;
for(const dialog of document.querySelectorAll('dialog')){dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});dialog.addEventListener('close',()=>{studyRun++;if(dialog.id==='share-dialog'){shareRenderRun++;clearStoryImages();shareVerse=null;shareRef=null;dialog.querySelector('textarea')?.remove();}if(currentCard&&currentRef)dwell(currentCard,currentRef);});}
document.addEventListener('click',event=>{const result=event.target.closest('[data-search-ref]');if(!result)return;const ref=parseKey(result.dataset.searchRef);if(ref)openReader(ref.s,ref.a);});
document.addEventListener('click',e=>{const step=e.target.closest('[data-step]');if(step){stepVerse(Number(step.dataset.step),step.closest('.verse'));return;}const close=e.target.closest('[data-close]');if(close){$(close.dataset.close).close();return;}const study=e.target.closest('[data-study]');if(study){selectStudy(study.dataset.study);return;}const go=e.target.closest('[data-go-view]');if(go){setView(go.dataset.goView);return;}const reader=e.target.closest('[data-read-surah]');if(reader){openReader(Number(reader.dataset.readSurah));return;}const open=e.target.closest('[data-open-ref]');if(open){const ref=parseKey(open.dataset.openRef);if(ref){$('learn-dialog').close();openReader(ref.s,ref.a);}return;}const act=e.target.closest('[data-action]');if(act){const ref=parseKey(act.dataset.key);if(!ref)return;switch(act.dataset.action){case'save':toggleSave(ref);break;case'share':share(ref);break;case'study':if($('learn-dialog').open){learnRef=ref;$('learn-title').textContent=`${index[ref.s-1].latin} · ${refKey(ref)}`;selectStudy('words');}else openLearn(ref);break;case'audio':play(ref);break;}return;}const retry=e.target.closest('[data-retry]');if(retry){const r=retry.dataset.retry;if(r==='feed')moreFeed({force:true});else if(r==='refresh')feedController.refresh();else if(r==='start')start();else if(r==='foryou'){forYouDirty=true;renderForYou();}else if(r==='study')renderStudy();else if(r.startsWith('reader:')){const [,s,a]=r.split(':').map(Number);openReader(s,a);}}});
document.addEventListener('click',e=>{const open=e.target.closest('[data-story-open]');if(open){const ref=parseKey(open.dataset.storyOpen),draft=storyDraftStore().get(ref);if(ref&&draft)share(ref,draft);return;}const remove=e.target.closest('[data-story-delete]');if(remove){const ref=parseKey(remove.dataset.storyDelete);if(ref&&storyDraftStore().remove(ref)){toast('Rancangan Story dihapus dari perangkat ini.');renderLibrary();}}});
document.querySelector('.study-tabs').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;const tabs=[...document.querySelectorAll('[data-study]')];let i=tabs.findIndex(b=>b.getAttribute('aria-selected')==='true');i=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;e.preventDefault();tabs[i].focus();selectStudy(tabs[i].dataset.study);});
document.addEventListener('keydown',event=>{
  if(modalOpen()||!['feed','foryou','reader'].includes(active)||event.target.closest('input,select,textarea,button,a')||!['ArrowDown','ArrowUp','PageDown','PageUp'].includes(event.key))return;
  const down=event.key==='ArrowDown'||event.key==='PageDown',content=event.target.closest('.verse-text');
  if(content&&content.scrollHeight>content.clientHeight+2&&(down?content.scrollTop+content.clientHeight<content.scrollHeight-2:content.scrollTop>2))return;
  event.preventDefault();stepVerse(down?1:-1);
});
