start();

let workerSetup=false;
function setupWorker(){
  if(workerSetup||!('serviceWorker'in navigator))return;workerSetup=true;
  const hadController=!!navigator.serviceWorker.controller;
  const remember=()=>{if(!currentRef)return;const url=new URL(location.href);url.searchParams.set('s',currentRef.s);url.searchParams.set('a',currentRef.a);if(active==='reader')url.searchParams.set('mode','reader');else url.searchParams.delete('mode');history.replaceState(null,'',url);};
  navigator.serviceWorker.register('./sw.js').then(reg=>{
    const activate=()=>{if(document.hidden&&reg.waiting&&navigator.serviceWorker.controller)reg.waiting.postMessage({type:'skip-waiting'});};
    const watch=worker=>worker?.addEventListener('statechange',()=>{if(worker.state==='installed')activate();});
    watch(reg.installing);reg.addEventListener('updatefound',()=>watch(reg.installing));document.addEventListener('visibilitychange',activate);reg.update().catch(()=>{});activate();
  }).catch(()=>{});
  navigator.serviceWorker.addEventListener('controllerchange',()=>{if(!hadController)return;const reload=()=>{if(document.hidden){remember();location.reload();}};if(document.hidden)reload();else document.addEventListener('visibilitychange',reload);});
}
